cd /workspace && grep -rin "backslash\|escape\|quoted\|quote" --exclude-dir=.yecoding . ; echo "--- exit $? ---"; echo "=== docstrings mentioning values/quoting in main.py ==="; python - <<'PY'
import ast
src=open('dotenv/main.py').read()
t=ast.parse(src)
for n in ast.walk(t):
    if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)) and ast.get_docstring(n):
        d=ast.get_docstring(n)
        if any(k in d.lower() for k in ('value','quote','escape','parse')):
            print(f"L{n.lineno} {n.name}: {d.strip()}\n")
PY
